            r0, c0 = i * step, j * step
            tile = tuple(tuple(grid[r0 + r][c0 + c] for c in range(n))
                         for r in range(n))
            vals = {v for row in tile for v in row}
            if 3 not in vals and 2 in vals:
                tiles.append(tile)
    if not tiles:
        return [[0 if v == 3 else v for v in row] for row in grid]
    counts = Counter(tiles)
    seed = max(tiles, key=lambda t: (counts[t], -tiles.index(t)))

    for i in range(n):
        for j in range(n):
            r0, c0 = i * step, j * step
            tile = [list(grid[r0 + r][c0:c0 + n]) for r in range(n)]
            if any(v == 3 for row in tile for v in row):
                # The colored band occludes tiles; restore motif only at its 2-cells.
                if seed[i][j] == 2:
                    tile = [list(row) for row in seed]
                else:
                    tile = [[0] * n for _ in range(n)]
